// Le seus comandos no Telegram (texto ou botao), atualiza o banco
// e devolve as respostas. So obedece o seu chat.
// funciona com o no chamado Config ou Config1
let cfg;
try { cfg = $('Config1').first().json; } catch (e) { cfg = $('Config').first().json; }
const upd = $('Telegram Trigger').first().json;
const cb = upd.callback_query || null;
const msg = upd.message || (cb ? cb.message : null) || {};
const chatId = String((msg.chat || {}).id || '');
const tg = (metodo, corpo) => this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + cfg.TELEGRAM_TOKEN + '/' + metodo,
  body: corpo,
  json: true
});
const out = (...textos) => textos.filter(Boolean).map(t => ({ json: { chat_id: chatId, text: t } }));

// primeiro contato: te diz o seu chat id
if (!cb && (msg.text || '').trim() === '/start' && chatId !== String(cfg.MEU_CHAT_ID)) {
  return out('Seu chat id é ' + chatId + '. Cole ele em MEU_CHAT_ID no nó Config dos dois workflows.');
}
if (!chatId || chatId !== String(cfg.MEU_CHAT_ID)) return [];   // so voce comanda

let texto = '';
if (cb) {
  texto = String(cb.data || '').replace(':', ' ');   // "ok13:12" vira "ok13 12"
  try { await tg('answerCallbackQuery', { callback_query_id: cb.id }); } catch (e) {}
  // tira os botoes pra nao aprovar duas vezes
  try {
    await tg('editMessageReplyMarkup', {
      chat_id: chatId, message_id: cb.message.message_id, reply_markup: { inline_keyboard: [] }
    });
  } catch (e) {}
} else {
  texto = (msg.text || '').trim();
}

if (/^\/(start|ajuda)$/i.test(texto)) {
  return out(
    'Comandos:\n' +
    'ok 12  ·  x 12  (ou use os botões)\n' +
    'ok 12 22  →  aprova e corrige o lado (13, 22 ou geral)\n' +
    'video <link> <13|22|ambos> <debate|entrevista|proposta|checagem|analise>\n' +
    'nota 3 12:40 por que vale ver\n' +
    'tirar video 3'
  );
}

const headers = {
  apikey: cfg.SUPABASE_SERVICE_KEY,
  Authorization: 'Bearer ' + cfg.SUPABASE_SERVICE_KEY,
  'Content-Type': 'application/json',
  Prefer: 'return=representation'
};

// placar de videos ativos por lado
const placarVideos = async () => {
  const ativos = await this.helpers.httpRequest({
    method: 'GET',
    url: cfg.SUPABASE_URL + '/rest/v1/videos?select=lado&ativo=eq.true',
    headers, json: true
  });
  let a = 0, b = 0;
  for (const r of ativos) {
    if (r.lado === '13' || r.lado === 'ambos') a++;
    if (r.lado === '22' || r.lado === 'ambos') b++;
  }
  let aviso = '';
  if (a - b >= 2) aviso = '\nAtenção: tem mais vídeo do 13. Equilibra com um do 22.';
  if (b - a >= 2) aviso = '\nAtenção: tem mais vídeo do 22. Equilibra com um do 13.';
  return 'Na LP agora: 13 → ' + a + ' | 22 → ' + b + aviso;
};

// "video <link> <13|22|ambos> [debate|entrevista|proposta|checagem|analise]"
const v = texto.match(/^v[ií]deo\s+(\S+)\s+(13|22|ambos)(?:\s+(debate|entrevista|proposta|checagem|an[aá]lise))?$/i);
if (v) {
  const link = v[1];
  const lado = v[2].toLowerCase();
  const categoria = (v[3] || 'entrevista').toLowerCase().replace('á', 'a');
  let titulo = link, fonte = '';
  try {
    const o = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://www.youtube.com/oembed?format=json&url=' + encodeURIComponent(link),
      json: true
    });
    titulo = o.title || link;
    fonte = o.author_name || '';
  } catch (e) { /* nao e YouTube ou saiu do ar: fica com o link */ }
  const novo = await this.helpers.httpRequest({
    method: 'POST',
    url: cfg.SUPABASE_URL + '/rest/v1/videos',
    headers,
    body: { link, lado, categoria, titulo, fonte, ativo: true },
    json: true
  });
  const id = Array.isArray(novo) && novo[0] ? novo[0].id : '?';
  return out(
    'Vídeo #' + id + ' adicionado (' + categoria + ', ' + lado + '):\n' + titulo +
    (fonte ? '\n' + fonte : '') + '\n\n' + await placarVideos() +
    '\n\nPra pôr a nota: nota ' + id + ' 12:40 por que vale ver' +
    '\nPra tirar: tirar video ' + id
  );
}

// "nota 12 [12:40] texto da analise"
const nt = texto.match(/^nota\s+#?(\d+)\s+(?:(\d{1,2}:\d{2}(?::\d{2})?)\s+)?([\s\S]+)$/i);
if (nt) {
  const corpo = { analise: nt[3].trim().slice(0, 280) };
  if (nt[2]) corpo.momento = nt[2];
  const r = await this.helpers.httpRequest({
    method: 'PATCH',
    url: cfg.SUPABASE_URL + '/rest/v1/videos?id=eq.' + nt[1],
    headers,
    body: corpo,
    json: true
  });
  if (!Array.isArray(r) || !r[0]) return out('Não achei o vídeo #' + nt[1] + '.');
  return out(
    'Nota salva no vídeo #' + nt[1] + (nt[2] ? ' (ponto-chave em ' + nt[2] + ')' : '') + ':\n' + corpo.analise +
    (nt[3].trim().length > 280 ? '\n\n(Cortei em 280 caracteres.)' : '')
  );
}

// "tirar video 12"
const t = texto.match(/^tirar\s+v[ií]deo\s+#?(\d+)$/i);
if (t) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: cfg.SUPABASE_URL + '/rest/v1/videos?id=eq.' + t[1],
    headers,
    body: { ativo: false },
    json: true
  });
  return out('Vídeo #' + t[1] + ' saiu da LP.\n\n' + await placarVideos());
}

// botões: ok13:12, ok22:12, okg:12, x:12 (ok:12 = aprova sem mexer no lado)
// texto:  ok 12, ok 12 22, ok 12 geral, x 12
let m = texto.match(/^(ok|x)(13|22|g)?\s+#?(\d+)(?:\s+(13|22|geral|g|ambos))?$/i);
if (!m) return out('Não entendi. Manda /ajuda pra ver os comandos.');

const aprovar = m[1].toLowerCase() === 'ok';
const id = m[3];
const pedido = String(m[2] || m[4] || '').toLowerCase();
const novoLado = pedido === '13' || pedido === '22' ? pedido : pedido ? 'ambos' : null;

const atualizadas = await this.helpers.httpRequest({
  method: 'PATCH',
  url: cfg.SUPABASE_URL + '/rest/v1/noticias?id=eq.' + id,
  headers,
  body: aprovar
    ? Object.assign({ status: 'aprovado', aprovado_em: new Date().toISOString() }, novoLado ? { lado: novoLado } : {})
    : { status: 'descartado' },
  json: true
});
const n = Array.isArray(atualizadas) ? atualizadas[0] : null;
if (!n) return out('Não achei a notícia #' + id + '.');
if (!aprovar) return out('#' + id + ' descartada.');

// placar do dia (horario de Brasilia)
const hoje = new Date(Date.now() - 3 * 3600 * 1000).toISOString().slice(0, 10) + 'T03:00:00Z';
const dia = await this.helpers.httpRequest({
  method: 'GET',
  url: cfg.SUPABASE_URL + '/rest/v1/noticias?select=lado&status=eq.aprovado&aprovado_em=gte.' + hoje,
  headers,
  json: true
});
let c13 = 0, c22 = 0;
for (const r of dia) {
  if (r.lado === '13' || r.lado === 'ambos') c13++;
  if (r.lado === '22' || r.lado === 'ambos') c22++;
}
let aviso = '';
if (c13 - c22 >= 2) aviso = '\nAtenção: segura o 13 até o 22 alcançar.';
if (c22 - c13 >= 2) aviso = '\nAtenção: segura o 22 até o 13 alcançar.';

const rotulo = { '13': '13 · Lula (PT)', '22': '22 · Flávio Bolsonaro (PL)', 'ambos': 'Geral' }[n.lado] || 'Geral';
const post =
  '*' + n.manchete + '*\n' +
  n.resumo + '\n\n' +
  rotulo + '\n' +
  'Fonte: ' + n.veiculo + ' · ' + n.link;

// duas mensagens: o placar e o post sozinho, facil de copiar pro canal
return out(
  'Aprovada #' + id + ' como ' + ({ '13': '13', '22': '22' }[n.lado] || 'Geral') + '. Hoje: 13 → ' + c13 + ' | 22 → ' + c22 + aviso + '\n\nO post vem na próxima mensagem. Copia e cola no canal.',
  post
);
